```java src/pag/domains/gen/LinearOpaqueIntervalDomain.java
package pag.domains.gen;

import java.math.BigInteger;
import java.util.*;
import pag.api.*;

/**
 * A backward abstract domain combining:
 *  - linear interval constraints over integer variables,
 *  - nonzero constraints for linear forms,
 *  - opaque interval constraints for non-linear expressions,
 *  - some built-in knowledge about squares.
 *
 * The domain is intentionally over-approximating.  It tries to be precise for
 * linear arithmetic and for repeated non-linear subexpressions, while remaining
 * sound for the rest.
 */
public class LinearOpaqueIntervalDomain implements Domain<LinearOpaqueIntervalDomain.State> {

    private static final State TOP =
            new State(false, Map.of(), Map.of(), Set.of(), Set.of(), Map.of());
    private static final State BOTTOM =
            new State(true, Map.of(), Map.of(), Set.of(), Set.of(), Map.of());

    public static final class State {
        final boolean bottom;
        final Map<LinearForm, Interval> lin;
        final Map<String, OpaqueConstraint> opaque;
        final Set<NonzeroLinear> linNonzero;
        final Set<OpaqueNonzero> opaqueNonzero;
        final Map<String, Interval> varIntervals;

        State(boolean bottom,
              Map<LinearForm, Interval> lin,
              Map<String, OpaqueConstraint> opaque,
              Set<NonzeroLinear> linNonzero,
              Set<OpaqueNonzero> opaqueNonzero,
              Map<String, Interval> varIntervals) {
            this.bottom = bottom;
            this.lin = Map.copyOf(lin);
            this.opaque = Map.copyOf(opaque);
            this.linNonzero = Set.copyOf(linNonzero);
            this.opaqueNonzero = Set.copyOf(opaqueNonzero);
            this.varIntervals = Map.copyOf(varIntervals);
        }

        boolean isTop() {
            return !bottom
                    && lin.isEmpty()
                    && opaque.isEmpty()
                    && linNonzero.isEmpty()
                    && opaqueNonzero.isEmpty();
        }
    }

    public LinearOpaqueIntervalDomain() {
    }

    @Override
    public String name() {
        return "LinearOpaqueIntervalDomain";
    }

    @Override
    public State top() {
        return TOP;
    }

    @Override
    public State bottom() {
        return BOTTOM;
    }

    @Override
    public boolean isBottom(State s) {
        return s.bottom;
    }

    @Override
    public boolean entails(State a, State b) {
        if (a.bottom) {
            return true;
        }
        if (b.bottom) {
            return false;
        }
        if (b.isTop()) {
            return true;
        }

