static LinearExpr substituteLinear(LinearExpr e, String var, LinearExpr src) {
  if !e.coeff.containsKey(var) return e;
  BigInteger c = e.coeff.get(var);
  Map<String,BigInteger> newCoeff = new TreeMap<>(e.coeff); newCoeff.remove(var);
