static LinearExpr linearize(Expr e) {
  if e instanceof ConstExpr c: return LinearExpr.constant(c.v)
  if e instanceof VarExpr v: return LinearExpr.var(v.name)
  if e instanceof AddExpr a:
     LinearExpr sum = constant(0)
     for term in a.terms:
        LinearExpr t = linearize(term); if null return null
        sum = sum.add(t)
     return sum
  if e instanceof MultExpr m:
     LinearExpr result = constant(ONE)
     boolean nonConst = false
     for factor in m.factors:
        LinearExpr f = linearize(factor); if null return null
        if f.coeff.isEmpty():
           result = result.multiplyConst(f.const)
        else:
           if nonConst return null
           result = result.multiplyLinear(f)
           nonConst = true
     return result
  if e instanceof CmpExpr: return null
}
