private static Interval computeInterval(LinearForm f, Map<String,Interval> varInt) {
  if (f.isEmpty()) return new Interval(ZERO, ZERO);
  BigInteger lo = ZERO, hi = ZERO;
  boolean loInf = false, hiInf = false;
  for (Map.Entry<String,BigInteger> e : f.coeff().entrySet()) {
    Interval vi = varInt.get(e.getKey());
    if (vi == null) vi = Interval.TOP;
    if (vi.isBottom()) return Interval.BOTTOM;
    BigInteger c = e.getValue();
    if (c.signum() == 0) continue;
    if (c.signum() > 0) {
       if (vi.lo() != null) lo = lo.add(vi.lo().multiply(c)); else loInf = true;
       if (vi.hi() != null) hi = hi.add(vi.hi().multiply(c)); else hiInf = true;
    } else {
       if (vi.hi() != null) lo = lo.add(vi.hi().multiply(c)); else loInf = true;
       if (vi.lo() != null) hi = hi.add(vi.lo().multiply(c)); else hiInf = true;
    }
  }
  return new Interval(loInf ? null : lo, hiInf ? null : hi);
}
