void addLinear(LinearExpr e, Interval I) {
  if (bottom) return;
  if (I.isBottom()) { bottom=true; return; }
  if (e.isConstant()) {
    if (!I.contains(e.const())) bottom=true;
    return;
  }
  LinearForm f = new LinearForm(e.coeff());
  Interval shifted = I.shift(e.const().negate());
  if (shifted.isBottom()) { bottom=true; return; }
  Interval old = lin.get(f);
  Interval newI = (old == null) ? shifted : old.intersect(shifted);
  if (newI.isBottom()) { bottom=true; return; }
  if (newI.isTop()) {
    if (old != null) lin.remove(f);
  } else {
    lin.put(f, newI);
  }
  // clean nonzero
  Iterator<NonzeroLinear> it = linNonzero.iterator();
  while (it.hasNext()) {
    NonzeroLinear nz = it.next();
    if (nz.form().equals(f)) {
      Interval sh = newI.shift(nz.const());
      if (sh.isZero()) { bottom=true; return; }
      if (sh.excludesZero()) it.remove();
    }
  }
}
