private State join(State a, State b) {
  if (a.bottom) return b;
  if (b.bottom) return a;
  if (a.isTop() || b.isTop()) return top();
  Set<LinearForm> forms = new HashSet<>();
  forms.addAll(a.lin.keySet()); forms.addAll(b.lin.keySet());
  for (NonzeroLinear nz : a.linNonzero) forms.add(nz.form());
  for (NonzeroLinear nz : b.linNonzero) forms.add(nz.form());
  // add variable forms
  for (LinearForm f : new ArrayList<>(forms)) for (String v : f.coeff().keySet()) forms.add(LinearForm.var(v));
  Map<LinearForm,Interval> lin = new HashMap<>();
  for (LinearForm f : forms) {
    if (f.isEmpty()) continue;
    Interval Ia = impliedLinearInterval(a, f);
    Interval Ib = impliedLinearInterval(b, f);
    Interval J = Ia.join(Ib);
    if (!J.isTop()) lin.put(f, J);
  }
  Set<NonzeroLinear> nz = new HashSet<>();
  nz.addAll(a.linNonzero); nz.addAll(b.linNonzero);
  for (LinearForm f : forms) {
    NonzeroLinear zero = new NonzeroLinear(f, BigInteger.ZERO);
    if (impliesNonzeroLinear(a, zero) && impliesNonzeroLinear(b, zero)) nz.add(zero);
  }
  // clean nz redundant? close will.
  // opaque
  Map<String,OpaqueConstraint> opaque = new HashMap<>();
  Set<String> keys = new HashSet<>(a.opaque.keySet()); keys.addAll(b.opaque.keySet());
  for (String key : keys) {
    OpaqueConstraint oa = a.opaque.get(key); OpaqueConstraint ob = b.opaque.get(key);
    if (oa != null && ob != null) {
      Interval J = oa.interval().join(ob.interval());
      if (!J.isTop()) opaque.put(key, new OpaqueConstraint(key, oa.vars(), oa.expr(), J));
    }
  }
  Set<OpaqueNonzero> opaqueNz = new HashSet<>();
  Set<OpaqueNonzero> candNz = new HashSet<>(a.opaqueNonzero); candNz.addAll(b.opaqueNonzero);
  for (OpaqueNonzero oz : candNz) {
    if (impliesOpaqueNonzero(a, oz) && impliesOpaqueNonzero(b, oz)) opaqueNz.add(oz);
  }
  StateBuilder bld = new StateBuilder();
  bld.lin = lin; bld.opaque = opaque; bld.linNonzero = nz; bld.opaqueNonzero = opaqueNz;
  return close(bld);
}
