private State widen(State a, State b) {
  if (a.bottom) return b;
  if (b.bottom) return a;
  if (a.isTop() || b.isTop()) return top();
  Set<LinearForm> forms = new HashSet<>(a.lin.keySet());
  for (NonzeroLinear nz : a.linNonzero) forms.add(nz.form());
  for (LinearForm f : new ArrayList<>(forms)) for (String v : f.coeff().keySet()) forms.add(LinearForm.var(v));
  Map<LinearForm,Interval> lin = new HashMap<>();
  for (LinearForm f : forms) {
    if (f.isEmpty()) continue;
    Interval Ia = impliedLinearInterval(a, f);
